// ── ICFEr: classificação de 2026 e links entre os itens de IC
CONDICOES.forEach(c => {
  if (c.id === "cr-ic" && c.guia && c.guia.secoes) {
    const s0 = c.guia.secoes.find(s => s.t === "Classificação");
    if (s0) {
      s0.b = [
        {tab: {h: ["Fração de ejeção", "Diretrizes 2026 (ESC e SBC)", "O que reduz eventos"], r: [
          ["≤ 40%", "IC com FE reduzida", "4 pilares (ver abaixo) – base dos ECR e do PCDT [F]"],
          ["41–49%", "Passou a ser IC com FE reduzida (a categoria 'levemente reduzida' foi extinta)", "iSGLT2 e ARM têm ECR nessa faixa [C]; para IECA/BRA/INRA e betabloqueador o benefício é extrapolado dos ECR com FE ≤ 40% [I]"],
          ["≥ 50%", "IC com FE preservada", "iSGLT2 + espironolactona – ver 'IC com FE preservada'"]]},
         nota: "ESC 2026 [F] e SBC 2026 (via resumo) [F]. O PCDT de ICFEr (2024) e o CEAF seguem exigindo FEVE ≤ 40% para dapagliflozina e ≤ 35% para sacubitril-valsartana [F]. Dapagliflozina para FE > 40%: não incorporada (CONITEC, dez/2025) [F]."},
        {ir: IC_LINKS},
        {ref: ["esc_ic2026", "sbc_ic2026", "pcdt_ic", "dapa_ic"]}
      ];
    }
    ["esc_ic2026", "sbc_ic2026"].forEach(k => { if (c.evid && !c.evid.fontes.includes(k)) c.evid.fontes.push(k); });
    c.nv = (c.nv || []).concat(["Rever o item inteiro à luz das diretrizes de IC de 2026 (ESC e SBC): doses, metas de titulação em 8 semanas, digoxina em baixa dose."]);
    c.mudancas = (c.mudancas || []).concat(["Revisão 19/10/2026 (v41): tabela de classificação atualizada para as diretrizes de 2026 (FE < 50% = reduzida; ≥ 50% = preservada) e links para o novo item de ICFEP."]);
  }
  if (c.id === "ic-descompensada") {
    c.mudancas = (c.mudancas || []).concat(["Revisão 19/10/2026 (v41): links para os itens de seguimento de ICFEr e ICFEP."]);
    if (!c.guia) c.encaminhar = (c.encaminhar || "") + " Seguimento: ver itens 'IC com FE reduzida' e 'IC com FE preservada' (Crônicos).";
  }
  if (c.id === "febre-adulto" && c.tags && !/maculosa/.test(c.tags)) c.tags += " febre maculosa carrapato";
});
